#!/bin/sh
# Preview the Hornero greeter with sddm-greeter-qt6 in test mode.
#
# Stages a throwaway theme directory under ${TMPDIR:-/tmp} that reuses this
# repository read-only (symlinked components and metadata), writes a preview
# theme.conf, and runs the greeter. Probe flags edit a COPY of Main.qml
# inside the stage dir only; the repository file is never modified. No
# media, no downloads: the background is generated by the theme itself.
#
# Usage:
#   scripts/preview.sh [flags]
#
#   --grab FILE       render offscreen (QT_QPA_PLATFORM=offscreen, --size WxH,
#                     default 1920x1080) and have the STAGED Main.qml grab its
#                     own frame to FILE; no display or compositor needed. With
#                     --screens 2 the second output is saved as FILE with a
#                     "-secondary" suffix before the extension.
#   --size WxH        offscreen output size (default 1920x1080)
#   --scale N         device pixel ratio / QT_SCALE_FACTOR (default 1)
#   --screens N       offscreen outputs side by side (1 or 2; default 1)
#   --scheme S        colorScheme: auto | night | day (default auto)
#   --high-contrast / --large-text / --reduced-motion
#                     theme.conf accessibility toggles
#   --lang L          language: auto | en | es (default auto)
#   --seed N          pin the generative sky (default 7 for grabs)
#   --plain           background=plain (no generative horizon)
#   --background PATH opt-in user image/video (theme.conf backgroundImage)
#   --fixture         staged-only: fixture accounts, Desktop/Studio/Gaming
#                     sessions, host name and a pinned clock, so renders are
#                     reproducible and show no real account (default with
#                     --grab; --host-models keeps the machine's real models)
#   --host-models     use the real userModel/sessionModel/hostName
#   --time HH:MM      staged-only: pin the clock (default 21:40 with --fixture)
#   --no-users        staged-only: no accounts listed (typed user name)
#   --no-sessions     staged-only: no sessions installed (honest error)
#   --one-user        staged-only: a single account
#   --many-users      staged-only: nine accounts (channel strip scrolls)
#   --power           staged-only: show suspend/restart/shut down even when
#                     test mode reports no power permissions
#   --confirm KIND    staged-only: open the power confirmation for KIND
#                     (suspend | restart | shutdown) after start
#   --fail-login [N]  staged-only: drive the production onLoginFailed handler
#                     N times (default 1) to render the failure state
#   --caps-lock       staged-only: report Caps Lock on
#   --open-sessions   staged-only: open the session list after start
#   --other-user      staged-only: tune the "Other" channel (typed name)
#   --keyboard        staged-only: virtualKeyboardAvailable=true
#   --no-branding     staged-only: brandingEnabled=false
#   --shot FILE       live window: capture the compositor with grim (Wayland)
#                     or ffmpeg x11grab after --delay SECS (default 4)
#   --run-secs N      stop the live greeter after N seconds
#   --keep            keep the staged theme directory
set -eu

ROOT=$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)
STAGE=$(mktemp -d "${TMPDIR:-/tmp}/greeter-preview-XXXXXX")

GRAB=""
SIZE=1920x1080
SCALE=1
SCREENS=1
SCHEME=auto
HIGH_CONTRAST=0
LARGE_TEXT=0
REDUCED_MOTION=0
LANG_SET=auto
SEED=""
PLAIN=0
BACKGROUND=""
FIXTURE=""
TIME=""
USERS=default
NO_SESSIONS=0
POWER=0
CONFIRM=""
FAIL_LOGIN=0
CAPS=0
OPEN_SESSIONS=0
OTHER_USER=0
KEYBOARD=0
NO_BRANDING=0
SHOT=""
DELAY=4
RUN_SECS=""
KEEP=0

while [ $# -gt 0 ]; do
  case "$1" in
    --grab) GRAB="$2"; shift 2;;
    --size) SIZE="$2"; shift 2;;
    --scale) SCALE="$2"; shift 2;;
    --screens) SCREENS="$2"; shift 2;;
    --scheme) SCHEME="$2"; shift 2;;
    --high-contrast) HIGH_CONTRAST=1; shift;;
    --large-text) LARGE_TEXT=1; shift;;
    --reduced-motion) REDUCED_MOTION=1; shift;;
    --lang) LANG_SET="$2"; shift 2;;
    --seed) SEED="$2"; shift 2;;
    --plain) PLAIN=1; shift;;
    --background) BACKGROUND="$2"; shift 2;;
    --fixture) FIXTURE=1; shift;;
    --host-models) FIXTURE=0; shift;;
    --time) TIME="$2"; shift 2;;
    --no-users) USERS=none; shift;;
    --one-user) USERS=one; shift;;
    --many-users) USERS=many; shift;;
    --no-sessions) NO_SESSIONS=1; shift;;
    --power) POWER=1; shift;;
    --confirm) CONFIRM="$2"; shift 2;;
    --fail-login)
      if [ $# -gt 1 ] && [ "${2#-}" = "$2" ]; then FAIL_LOGIN="$2"; shift 2; else FAIL_LOGIN=1; shift; fi;;
    --caps-lock) CAPS=1; shift;;
    --open-sessions) OPEN_SESSIONS=1; shift;;
    --other-user) OTHER_USER=1; shift;;
    --keyboard) KEYBOARD=1; shift;;
    --no-branding) NO_BRANDING=1; shift;;
    --shot) SHOT="$2"; shift 2;;
    --delay) DELAY="$2"; shift 2;;
    --run-secs) RUN_SECS="$2"; shift 2;;
    --keep) KEEP=1; shift;;
    *) echo "unknown flag: $1" >&2; rm -rf "$STAGE"; exit 1;;
  esac
done

case "$SCHEME" in auto|night|day) ;; *) echo "bad --scheme: $SCHEME" >&2; exit 1;; esac
case "$LANG_SET" in auto|en|es) ;; *) echo "bad --lang: $LANG_SET" >&2; exit 1;; esac
case "$SCREENS" in 1|2) ;; *) echo "bad --screens: $SCREENS (1 or 2)" >&2; exit 1;; esac
case "$CONFIRM" in ""|suspend|restart|shutdown) ;; *) echo "bad --confirm: $CONFIRM" >&2; exit 1;; esac

if [ -z "$FIXTURE" ]; then
  if [ -n "$GRAB" ]; then FIXTURE=1; else FIXTURE=0; fi
fi
if [ "$FIXTURE" = 1 ] && [ -z "$TIME" ]; then TIME=21:40; fi
if [ -n "$GRAB" ] && [ -z "$SEED" ]; then SEED=7; fi
if [ -n "$SHOT" ] && [ -z "$RUN_SECS" ]; then RUN_SECS=$((DELAY + 3)); fi

ln -s "$ROOT/components" "$STAGE/components"
ln -s "$ROOT/metadata.desktop" "$STAGE/metadata.desktop"
cp "$ROOT/Main.qml" "$STAGE/Main.qml"

flag() { if [ "$1" = 1 ]; then echo true; else echo false; fi; }

# Preview theme.conf: the repository defaults plus the requested toggles.
BG=horizon
[ "$PLAIN" = 1 ] && BG=plain
python3 - "$ROOT/theme.conf" "$STAGE/theme.conf" \
  "colorScheme=$SCHEME" "language=$LANG_SET" \
  "highContrast=$(flag "$HIGH_CONTRAST")" \
  "largeText=$(flag "$LARGE_TEXT")" \
  "reducedMotion=$(flag "$REDUCED_MOTION")" \
  "backgroundSeed=$SEED" "background=$BG" "backgroundImage=$BACKGROUND" \
  "virtualKeyboardAvailable=$(flag "$KEYBOARD")" \
  "brandingEnabled=$(flag $((1 - NO_BRANDING)))" <<'EOF'
import sys
src, dst, *pairs = sys.argv[1:]
want = dict(p.split("=", 1) for p in pairs)
out = []
for line in open(src, encoding="utf-8").read().splitlines():
    key = line.split("=", 1)[0]
    if "=" in line and not line.startswith(("#", ";")) and key in want:
        line = f"{key}={want.pop(key)}"
    out.append(line)
out += [f"{k}={v}" for k, v in want.items()]
open(dst, "w", encoding="utf-8").write("\n".join(out) + "\n")
EOF

# Staged-copy probes. Each asserts its anchor so a refactor that breaks a
# probe fails loudly instead of rendering the wrong state.
python3 - "$STAGE/Main.qml" "$FIXTURE" "$USERS" "$NO_SESSIONS" "$TIME" \
  "$POWER" "$CONFIRM" "$FAIL_LOGIN" "$CAPS" "$OPEN_SESSIONS" "$OTHER_USER" "$GRAB" <<'EOF'
import json
import sys

(path, fixture, users, no_sessions, pin, power, confirm, fail, caps,
 open_sessions, other, grab) = sys.argv[1:]
src = open(path, encoding="utf-8").read()


def sub(old, new, count=1):
    global src
    assert old in src, f"probe anchor not found: {old!r}"
    src = src.replace(old, new, count)


extra = []
if fixture == "1":
    people = {
        "default": [("ana", "Ana Quiroga"), ("tomi", "Tomás Ferreyra"), ("estudio", "")],
        "one": [("ana", "Ana Quiroga")],
        "many": [(f"user{i}", f"Account {i}") for i in range(1, 10)],
        "none": [],
    }[users]
    rows = "".join(
        f'        ListElement {{ name: {json.dumps(n)}; realName: {json.dumps(r)}; icon: "" }}\n'
        for n, r in people
    )
    sessions = [] if no_sessions == "1" else [
        "HorneroOS Desktop", "HorneroOS Studio", "HorneroOS Gaming (Experimental)", "Plasma (Wayland)",
    ]
    srows = "".join(
        f'        ListElement {{ name: {json.dumps(n)}; file: "fixture.desktop" }}\n' for n in sessions
    )
    extra.append("    ListModel {\n        id: fixtureUsers\n" + rows + "    }\n")
    extra.append("    ListModel {\n        id: fixtureSessions\n" + srows + "    }\n")
    sub("property var userSource: userModel", "property var userSource: fixtureUsers")
    sub("property string lastUser: userModel.lastUser", 'property string lastUser: "ana"')
    sub("property var sessionSource: sessionModel", "property var sessionSource: fixtureSessions")
    sub("property int sessionLastIndex: sessionModel.lastIndex", "property int sessionLastIndex: 0")
    src = src.replace("sddm.hostName", '"hornero-qa"')
elif users == "none" or no_sessions == "1":
    print("--no-users/--no-sessions need --fixture", file=sys.stderr)
    sys.exit(2)
if pin:
    hh, mm = (int(x) for x in pin.split(":"))
    fixed = f"new Date(2026, 10, 18, {hh}, {mm}, 0)"
    sub("property date now: new Date()", f"property date now: {fixed}")
    sub("onTriggered: container.now = new Date()", f"onTriggered: container.now = {fixed}")
if power == "1" or confirm:
    for name in ("sddm.canSuspend", "sddm.canReboot", "sddm.canPowerOff"):
        sub(f"visible: {name}", "visible: true")
if caps == "1":
    sub("if (keyboard.capsLock)", "if (true)")
steps = []
if other == "1":
    steps.append("channels.tune(channels.count - 1); username_input_box.forceActiveFocus();")
for _ in range(int(fail or 0)):
    steps.append("sddm.loginFailed();")
if open_sessions == "1":
    steps.append("session.openList();")
if confirm:
    steps.append(f'container.requestPower("{confirm}");')
if steps:
    extra.append(
        "    Timer {\n        interval: 1200\n        running: true\n        onTriggered: {\n"
        + "".join(f"            {s}\n" for s in steps)
        + "        }\n    }\n"
    )
if grab:
    dot = grab.rfind(".")
    secondary = grab[:dot] + "-secondary" + grab[dot:] if dot > 0 else grab + "-secondary"
    extra.append(
        "    Timer {\n        interval: 3500\n        running: true\n"
        "        onTriggered: container.grabToImage(function (r) {\n"
        f"            r.saveToFile(container.isPrimary ? {json.dumps(grab)} : {json.dumps(secondary)});\n"
        "        })\n    }\n"
        "    Timer {\n        interval: 4800\n        running: true\n        onTriggered: Qt.quit()\n    }\n"
    )
src = src.rstrip()
assert src.endswith("}"), "Main.qml root not found"
src = src[:-1] + "".join(extra) + "}\n"
open(path, "w", encoding="utf-8").write(src)
EOF

echo "preview theme staged at $STAGE"
if [ "$KEEP" = 1 ]; then echo "(keeping stage dir)"; fi

GREETER_PID=""
cleanup() {
  if [ -n "$GREETER_PID" ]; then
    kill "$GREETER_PID" 2>/dev/null || true
  fi
  if [ "$KEEP" = 0 ]; then
    rm -rf "$STAGE"
  fi
}
trap cleanup EXIT INT TERM

if [ -n "$GRAB" ]; then
  CONF="$STAGE/offscreen.json"
  W=${SIZE%x*}
  H=${SIZE#*x}
  if [ "$SCREENS" = 2 ]; then
    printf '{"screens":[{"name":"DP-1","x":0,"y":0,"width":%s,"height":%s,"logicalDpiX":96,"logicalDpiY":96,"dpr":%s},{"name":"HDMI-A-1","x":%s,"y":0,"width":%s,"height":%s,"logicalDpiX":96,"logicalDpiY":96,"dpr":%s}]}\n' \
      "$W" "$H" "$SCALE" "$W" "$W" "$H" "$SCALE" > "$CONF"
  else
    printf '{"screens":[{"name":"DP-1","x":0,"y":0,"width":%s,"height":%s,"logicalDpiX":96,"logicalDpiY":96,"dpr":%s}]}\n' \
      "$W" "$H" "$SCALE" > "$CONF"
  fi
  # Never report a previous frame as this capture.
  rm -f -- "$GRAB"
  QT_QPA_PLATFORM="offscreen:configfile=$CONF" timeout 60 \
    sddm-greeter-qt6 --test-mode --theme "$STAGE" >"$STAGE/greeter.log" 2>&1 || true
  if [ ! -s "$GRAB" ]; then
    echo "offscreen grab failed: $GRAB" >&2
    tail -n 30 "$STAGE/greeter.log" >&2 || true
    exit 1
  fi
  grep -E "qml|QML|TypeError|ReferenceError" "$STAGE/greeter.log" | grep -v "^$" | head -n 20 >&2 || true
  echo "offscreen frame saved to $GRAB"
  exit 0
fi

QT_SCALE_FACTOR="$SCALE" sddm-greeter-qt6 --test-mode --theme "$STAGE" &
GREETER_PID=$!

if [ -n "$SHOT" ]; then
  sleep "$DELAY"
  if command -v grim >/dev/null 2>&1 && [ -n "${WAYLAND_DISPLAY:-}" ]; then
    grim "$SHOT"
  else
    ffmpeg -y -loglevel error -f x11grab -i "${DISPLAY:-:0}" -frames:v 1 "$SHOT"
  fi
  echo "screenshot saved to $SHOT"
fi

if [ -n "$RUN_SECS" ]; then
  sleep "$RUN_SECS"
else
  wait "$GREETER_PID"
  GREETER_PID=""
fi
